import os
import io
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, List, Optional

import boto3


def _to_decimal(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        text = str(value).strip().replace(",", "")
        if not text:
            return None
        return float(Decimal(text))
    except (InvalidOperation, ValueError, TypeError):
        return None


def _get_summary_field(expense_doc: Dict[str, Any], field_type: str) -> Optional[Dict[str, Any]]:
    for field in expense_doc.get("SummaryFields", []):
        if field.get("Type", {}).get("Text") == field_type:
            return field
    return None


def _field_value_text(field: Optional[Dict[str, Any]]) -> Optional[str]:
    if not field:
        return None
    value_detection = field.get("ValueDetection") or {}
    text = value_detection.get("Text")
    if text:
        return text.strip()
    label_detection = field.get("LabelDetection") or {}
    label = label_detection.get("Text")
    return label.strip() if label else None


def _field_value_number(field: Optional[Dict[str, Any]]) -> Optional[float]:
    text = _field_value_text(field)
    return _to_decimal(text)


def _normalize_line_items(expense_doc: Dict[str, Any]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for group in expense_doc.get("LineItemGroups", []):
        for line_item in group.get("LineItems", []):
            normalized: Dict[str, Any] = {
                "description": None,
                "quantity": None,
                "unit_price": None,
                "total": None,
                "product_code": None,
            }
            for field in line_item.get("LineItemExpenseFields", []):
                field_type = field.get("Type", {}).get("Text")
                text = _field_value_text(field)
                if field_type == "ITEM":
                    normalized["description"] = text
                elif field_type == "QUANTITY":
                    normalized["quantity"] = _to_decimal(text)
                elif field_type == "PRICE":
                    normalized["unit_price"] = _to_decimal(text)
                elif field_type == "PRODUCT_CODE":
                    normalized["product_code"] = text
                elif field_type in ("LINE_ITEM_PRICE", "AMOUNT"):
                    normalized["total"] = _to_decimal(text)
            if any(v is not None for v in normalized.values()):
                items.append(normalized)
    return items


def extract_invoice_fields(file_path: str, region_name: Optional[str] = None) -> Dict[str, Any]:
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1")

    with open(file_path, "rb") as f:
        document_bytes = f.read()

    response = client.analyze_expense(
        Document={
            "Bytes": document_bytes
        }
    )

    expense_documents = response.get("ExpenseDocuments", [])
    if not expense_documents:
        return {
            "vendor": None,
            "date": None,
            "total": None,
            "line_items": [],
        }

    expense_doc = expense_documents[0]

    vendor_field = _get_summary_field(expense_doc, "VENDOR_NAME")
    date_field = _get_summary_field(expense_doc, "INVOICE_RECEIPT_DATE")
    total_field = _get_summary_field(expense_doc, "TOTAL")

    return {
        "vendor": _field_value_text(vendor_field),
        "date": _field_value_text(date_field),
        "total": _field_value_number(total_field),
        "line_items": _normalize_line_items(expense_doc),
    }
